{% include base_path %}
{% include group-by-array collection=site.posts field="categories" %}

{% for category in group_names %}
  {% assign posts = group_items[forloop.index0] %}
  <h2 id="{{ category | slugify }}" class="archive__subtitle">{{ category }}</h2>
  {% for post in posts %}
    {% include archive-single.html %}
  {% endfor %}
{% endfor %}

{% include base_path %}
{% capture written_label %}'None'{% endcapture %}

{% for collection in site.collections %}
  {% unless collection.output == false or collection.label == "posts" %}
    {% capture label %}{{ collection.label }}{% endcapture %}
    {% if label != written_label %}
      <h2 id="{{ label | slugify }}" class="archive__subtitle">{{ label }}</h2>
      {% capture written_label %}{{ label }}{% endcapture %}
    {% endif %}
  {% endunless %}
  {% for post in collection.docs %}
    {% unless collection.output == false or collection.label == "posts" %}
      {% include archive-single.html %}
    {% endunless %}
  {% endfor %}
{% endfor %}

{% include base_path %}

{% assign videos = site.media | where: "category", "video" %}
{% assign articles = site.media | where: "category", "article" %}

{% if videos.size > 0 %}
  <section class="media-section" aria-labelledby="media-videos-title">
    <div class="category-header">
      <h2 class="category-title" id="media-videos-title">Video interviews</h2>
    </div>
    <div class="media-list">
      {% for post in videos reversed %}
        {% include archive-single-media.html %}
      {% endfor %}
    </div>
  </section>
{% endif %}

{% if articles.size > 0 %}
  <section class="media-section" aria-labelledby="media-articles-title">
    <div class="category-header">
      <h2 class="category-title" id="media-articles-title">Articles</h2>
    </div>
    <div class="media-list">
      {% for post in articles reversed %}
        {% include archive-single-media.html %}
      {% endfor %}
    </div>
  </section>
{% endif %}

{% include base_path %}
{% for post in site.pages %}
  {% include archive-single.html %}
{% endfor %}

{% include base_path %}


{% for post in site.portfolio %}
  {% include archive-single.html %}
{% endfor %}

{% if site.data.services.analytics_enabled %}
This site counts page views to understand which pages are useful. It stores only a page path, a UTC calendar date, and an aggregate count, retained for up to 90 days. It does not use analytics cookies, visitor IDs, fingerprinting, or cross-site tracking. Search terms, URL query strings, referring pages, and IP addresses are not stored in the analytics database. Counts measure page views, not unique people, and may include automated traffic. The script respects Do Not Track and Global Privacy Control.
{% else %}
Site usage analytics are currently disabled.
{% endif %}

When enabled, the contact form sends your name, email address, subject, and message to me by email through Cloudflare and Resend. These services process the message to deliver it and prevent abuse. Messages are not saved in this website's database or repository. Cloudflare Turnstile checks submissions for spam. Network addresses are processed transiently for delivery and rate limiting.

GitHub Pages hosts the public site. GitHub, Cloudflare, and the email provider may process connection information and retain operational logs under their own policies. The application's analytics database contains no connection logs.

The private editor uses a short-lived, secure sign-in cookie and GitHub authentication. Drafts are stored privately in Cloudflare D1. Only the version the owner publishes is returned to visitors. Content edits do not create GitHub commits or pull requests. GitHub Pages continues to host the site’s layout and a baseline copy of the content.

Embedded videos and links to other websites have their own privacy practices. You may contact me about information you have sent through the [contact page](/contact/).

The owner editor stores uploaded PDFs and photos privately. Paper PDFs have no public download route. Photos become public only when added to a published page. Uploads used only in an unpublished draft stay private.

{% if site.author.googlescholar %}
  <a href="{{ site.author.googlescholar }}" class="btn publications-scholar-btn">
    <i class="fas fa-graduation-cap"></i> View on Google Scholar
  </a>
{% endif %}

{% include base_path %}

<form class="publication-filters" id="publication-filters" role="search" aria-label="Explore publications" hidden>
  <label class="publication-search">Search publications
    <input type="search" name="q" id="publication-query" placeholder="Title, journal, author, or keyword" autocomplete="off">
  </label>
  <label>Year<select name="year" id="publication-year"><option value="">All years</option></select></label>
  <label>Article type<select name="type" id="publication-type"><option value="">All types</option></select></label>
  <label>Topic<select name="topic" id="publication-topic"><option value="">All topics</option></select></label>
  <button type="reset" class="portfolio-button">Clear filters</button>
</form>
<p id="publication-count" role="status" aria-live="polite"></p>
<p id="publication-empty" hidden>No publications match these filters. Try a broader search or clear the filters.</p>
<noscript><p>All publications are listed below. Enable JavaScript to search and filter them.</p></noscript>
<script defer src="{{ '/assets/js/publications.js' | relative_url }}"></script>

<!-- New style rendering if publication categories are defined -->
{% if site.publication_category %}
  <div class="publications-container">
    {% for category in site.publication_category %}
      {% assign title_shown = false %}
      {% assign category_items = 0 %}

      <!-- Count items in category -->
      {% for post in site.publications %}
        {% if post.category == category[0] %}
          {% assign category_items = category_items | plus: 1 %}
        {% endif %}
      {% endfor %}

      {% if category_items > 0 %}
        <section class="publication-category">
          <div class="category-header">
            <h2 class="category-title">{{ category[1].title }}</h2>
          </div>
          <hr class="category-divider" />

          <div class="publications-list">
            {% for post in site.publications reversed %}
              {% if post.category == category[0] %}
                {% include archive-single-publication.html %}
              {% endif %}
            {% endfor %}
          </div>
        </section>
      {% endif %}
    {% endfor %}
  </div>
{% else %}
  <div class="publications-container">
    <div class="publications-list">
      {% for post in site.publications reversed %}
        {% include archive-single-publication.html %}
      {% endfor %}
    </div>
  </div>
{% endif %}

{% include base_path %}
{% include group-by-array collection=site.posts field="tags" %}

{% for tag in group_names %}
  {% assign posts = group_items[forloop.index0] %}
  <h2 id="{{ tag | slugify }}" class="archive__subtitle">{{ tag }}</h2>
  {% for post in posts %}
    {% include archive-single.html %}
  {% endfor %}
{% endfor %}

{% include base_path %}

{% if site.talkmap_link == true %}
<p style="text-decoration:underline;">
  <a href="/talkmap.html">See a map of all the places I've given a talk!</a>
</p>
{% endif %}

<!-- Define the categories -->
{% assign orals   = site.talks | where: "category", "orals" %}
{% assign posters = site.talks | where: "category", "posters" %}
{% assign invited = site.talks | where: "category", "invited" %}

<div class="publications-container">

  <!-- ORAL PRESENTATIONS -->
  {% if orals.size > 0 %}
    <section class="publication-category">
      <div class="category-header">
        <h2 class="category-title">Oral Presentations</h2>
      </div>
      <hr class="category-divider" />

      <div class="publications-list">
        {% for post in orals reversed %}
          <div class="talk-item">
            {% include archive-single-talk.html %}
          </div>
        {% endfor %}
      </div>
    </section>
  {% endif %}

  <!-- POSTER PRESENTATIONS -->
  {% if posters.size > 0 %}
    <section class="publication-category">
      <div class="category-header">
        <h2 class="category-title">Poster Presentations</h2>
      </div>
      <hr class="category-divider" />

      <div class="publications-list">
        {% for post in posters reversed %}
          <div class="talk-item">
            {% include archive-single-talk.html %}
          </div>
        {% endfor %}
      </div>
    </section>
  {% endif %}

  <!-- INVITED TALKS -->
  {% if invited.size > 0 %}
    <section class="publication-category">
      <div class="category-header">
        <h2 class="category-title">Invited Talks</h2>
      </div>
      <hr class="category-divider" />

      <div class="publications-list">
        {% for post in invited reversed %}
          <div class="talk-item">
            {% include archive-single-talk.html %}
          </div>
        {% endfor %}
      </div>
    </section>
  {% endif %}

</div>

{% include base_path %}

{% for post in site.teaching reversed %}
  {% include archive-single.html %}
{% endfor %}

{% include base_path %}
{% capture written_year %}'None'{% endcapture %}
{% for post in site.posts %}
  {% capture year %}{{ post.date | date: '%Y' }}{% endcapture %}
  {% if year != written_year %}
    <h2 id="{{ year | slugify }}" class="archive__subtitle">{{ year }}</h2>
    {% capture written_year %}{{ year }}{% endcapture %}
  {% endif %}
  {% include archive-single.html %}
{% endfor %}
